from pathlib import Path
ROOT = Path.cwd()
files = {'lib/agency-roster-migration.ts': 'export type RosterMigrationParseResult = {\n  rows: Array<{\n    raw: Record<string, string>;\n    normalized: Record<string, unknown>;\n  }>;\n  headers: string[];\n  fieldMapping: Record<string, string>;\n  errors: string[];\n};\n\nconst parseCsvRows = (text: string) => {\n  const rows: string[][] = [];\n  let row: string[] = [];\n  let cell = \'\';\n  let quoted = false;\n\n  for (let index = 0; index < text.length; index += 1) {\n    const char = text[index];\n\n    if (char === \'"\') {\n      if (quoted && text[index + 1] === \'"\') {\n        cell += \'"\';\n        index += 1;\n      } else {\n        quoted = !quoted;\n      }\n      continue;\n    }\n\n    if (char === \',\' && !quoted) {\n      row.push(cell);\n      cell = \'\';\n      continue;\n    }\n\n    if ((char === \'\\n\' || char === \'\\r\') && !quoted) {\n      if (char === \'\\r\' && text[index + 1] === \'\\n\') index += 1;\n      row.push(cell);\n      if (row.some((value) => value.trim())) rows.push(row);\n      row = [];\n      cell = \'\';\n      continue;\n    }\n\n    cell += char;\n  }\n\n  row.push(cell);\n  if (row.some((value) => value.trim())) rows.push(row);\n\n  if (quoted) {\n    throw new Error(\'CSV contains an unclosed quoted field.\');\n  }\n\n  return rows;\n};\n\nconst headerKey = (value: string) =>\n  value\n    .trim()\n    .toLowerCase()\n    .replace(/[^a-z0-9]+/g, \'_\')\n    .replace(/^_|_$/g, \'\');\n\nconst listValue = (value: string) =>\n  value\n    .split(/[;|]/)\n    .map((item) => item.trim())\n    .filter(Boolean);\n\nconst ALIASES: Record<string, string> = {\n  player: \'full_name\',\n  player_name: \'full_name\',\n  name: \'full_name\',\n  full_name: \'full_name\',\n  first: \'first_name\',\n  first_name: \'first_name\',\n  firstname: \'first_name\',\n  surname: \'last_name\',\n  last: \'last_name\',\n  last_name: \'last_name\',\n  lastname: \'last_name\',\n  preferred_name: \'preferred_name\',\n  known_as: \'preferred_name\',\n  dob: \'date_of_birth\',\n  birth_date: \'date_of_birth\',\n  date_of_birth: \'date_of_birth\',\n  nationality: \'nationalities\',\n  nationalities: \'nationalities\',\n  height: \'height_cm\',\n  height_cm: \'height_cm\',\n  foot: \'preferred_foot\',\n  preferred_foot: \'preferred_foot\',\n  position: \'primary_position\',\n  primary_position: \'primary_position\',\n  secondary_position: \'secondary_positions\',\n  secondary_positions: \'secondary_positions\',\n  club: \'current_club\',\n  current_club: \'current_club\',\n  league: \'current_league\',\n  current_league: \'current_league\',\n  country: \'current_country\',\n  current_country: \'current_country\',\n  status: \'football_status\',\n  football_status: \'football_status\',\n  contract_status: \'contract_status\',\n  contract_expiry: \'contract_expiry\',\n  contract_end: \'contract_expiry\',\n  transfermarkt: \'transfermarkt_url\',\n  transfermarkt_url: \'transfermarkt_url\',\n  wyscout: \'wyscout_url\',\n  wyscout_url: \'wyscout_url\',\n  instagram: \'instagram_url\',\n  instagram_url: \'instagram_url\',\n};\n\nconst splitFullName = (normalized: Record<string, unknown>) => {\n  if (\n    String(normalized.first_name || \'\').trim() ||\n    String(normalized.last_name || \'\').trim()\n  ) {\n    delete normalized.full_name;\n    return;\n  }\n\n  const fullName = String(normalized.full_name || \'\').trim();\n  if (!fullName) return;\n\n  const parts = fullName.split(/\\s+/).filter(Boolean);\n\n  if (parts.length === 1) {\n    normalized.first_name = parts[0];\n  } else {\n    normalized.first_name = parts.slice(0, -1).join(\' \');\n    normalized.last_name = parts.at(-1);\n  }\n\n  delete normalized.full_name;\n};\n\nexport function parseRosterMigrationCsv(\n  text: string,\n): RosterMigrationParseResult {\n  const csv = parseCsvRows(text.replace(/^\\uFEFF/, \'\'));\n\n  if (csv.length < 2) {\n    throw new Error(\'CSV needs a header row and at least one data row.\');\n  }\n\n  const rawHeaders = csv[0].map((value) => value.trim());\n  const canonicalHeaders = rawHeaders.map(\n    (value) => ALIASES[headerKey(value)] || headerKey(value),\n  );\n\n  const fieldMapping: Record<string, string> = {};\n  rawHeaders.forEach((header, index) => {\n    if (header) fieldMapping[header] = canonicalHeaders[index];\n  });\n\n  const errors: string[] = [];\n\n  const rows = csv\n    .slice(1)\n    .map((cells, rowIndex) => {\n      const raw: Record<string, string> = {};\n      const normalized: Record<string, unknown> = {};\n\n      rawHeaders.forEach((header, columnIndex) => {\n        const value = String(cells[columnIndex] || \'\').trim();\n        if (header) raw[header] = value;\n        if (!value) return;\n\n        const target = canonicalHeaders[columnIndex];\n        if (!target) return;\n\n        if (\n          target === \'nationalities\' ||\n          target === \'secondary_positions\'\n        ) {\n          normalized[target] = listValue(value);\n        } else {\n          normalized[target] = value;\n        }\n      });\n\n      splitFullName(normalized);\n\n      if (\n        !String(normalized.first_name || \'\').trim() &&\n        !String(normalized.last_name || \'\').trim() &&\n        !String(normalized.preferred_name || \'\').trim()\n      ) {\n        errors.push(`Row ${rowIndex + 2}: player name is required.`);\n      }\n\n      return { raw, normalized };\n    })\n    .filter((row) =>\n      Object.values(row.raw).some((value) => value.trim()),\n    );\n\n  return {\n    rows,\n    headers: rawHeaders,\n    fieldMapping,\n    errors,\n  };\n}\n\nexport const rosterMigrationTemplate = [\n  \'First Name,Last Name,Position,Current Club,Current League,Current Country,Date of Birth,Nationalities,Preferred Foot,Height CM,Contract Status,Contract Expiry,Transfermarkt URL\',\n  \'Alex,Example,RW,Example FC,Premier Division,Netherlands,2001-04-12,Netherlands;Belgium,Right,181,Under contract,2027-06-30,https://www.transfermarkt.com/example\',\n].join(\'\\n\');\n', 'components/AgencyRosterMigrationPanel.tsx': '\'use client\';\n\nimport {\n  CheckCircle2,\n  CircleAlert,\n  Download,\n  FileSpreadsheet,\n  LoaderCircle,\n  Upload,\n  X,\n} from \'lucide-react\';\nimport { ChangeEvent, useMemo, useState } from \'react\';\n\nimport {\n  parseRosterMigrationCsv,\n  rosterMigrationTemplate,\n} from \'@/lib/agency-roster-migration\';\n\nimport styles from \'./AgencyRosterMigrationPanel.module.css\';\n\ntype MigrationRow = {\n  row_id: string;\n  row_number: number;\n  validation_state: string;\n  proposed_action: string;\n  human_decision: string | null;\n  issues: Array<{ code?: string; message?: string }>;\n  normalized_data: Record<string, unknown>;\n};\n\ntype MigrationSnapshot = {\n  batch: {\n    id: string;\n    status: string;\n    row_count: number;\n    valid_rows: number;\n    warning_rows: number;\n    blocked_rows: number;\n  };\n  rows: MigrationRow[];\n  approval_gate: {\n    blocked_rows: number;\n    warnings_requiring_decision: number;\n    can_approve: boolean;\n  };\n};\n\nconst playerName = (row: MigrationRow) =>\n  [row.normalized_data?.first_name, row.normalized_data?.last_name]\n    .filter(Boolean)\n    .join(\' \') ||\n  String(row.normalized_data?.preferred_name || `Row ${row.row_number}`);\n\nexport default function AgencyRosterMigrationPanel({\n  workspaceName,\n  invoke,\n  onClose,\n  onImported,\n}: {\n  workspaceName: string;\n  invoke: (\n    action: string,\n    body?: Record<string, unknown>,\n  ) => Promise<any>;\n  onClose: () => void;\n  onImported: () => Promise<void> | void;\n}) {\n  const [csv, setCsv] = useState(\'\');\n  const [sourceName, setSourceName] = useState(\'Pasted CSV\');\n  const [migration, setMigration] =\n    useState<MigrationSnapshot | null>(null);\n  const [busy, setBusy] = useState(\'\');\n  const [error, setError] = useState(\'\');\n  const [applied, setApplied] = useState<any>(null);\n\n  const parsed = useMemo(() => {\n    if (!csv.trim()) return null;\n    try {\n      return parseRosterMigrationCsv(csv);\n    } catch {\n      return null;\n    }\n  }, [csv]);\n\n  const resetReview = () => {\n    setMigration(null);\n    setApplied(null);\n    setError(\'\');\n  };\n\n  const readFile = async (event: ChangeEvent<HTMLInputElement>) => {\n    const file = event.target.files?.[0];\n    if (!file) return;\n\n    if (file.size > 2_000_000) {\n      setError(\'Use a CSV smaller than 2 MB.\');\n      return;\n    }\n\n    setCsv(await file.text());\n    setSourceName(file.name);\n    resetReview();\n  };\n\n  const downloadTemplate = () => {\n    const blob = new Blob([rosterMigrationTemplate], {\n      type: \'text/csv;charset=utf-8\',\n    });\n    const url = URL.createObjectURL(blob);\n    const anchor = document.createElement(\'a\');\n    anchor.href = url;\n    anchor.download = \'player-roster-template.csv\';\n    anchor.click();\n    URL.revokeObjectURL(url);\n  };\n\n  const refreshBatch = async (batchId: string) => {\n    const response = await invoke(\'migration_batch\', {\n      batch_id: batchId,\n      limit: 1000,\n    });\n    setMigration(response?.migration || null);\n  };\n\n  const runPreflight = async () => {\n    setBusy(\'preview\');\n    setError(\'\');\n    setApplied(null);\n\n    try {\n      const next = parseRosterMigrationCsv(csv);\n\n      if (next.errors.length) {\n        throw new Error(next.errors.slice(0, 6).join(\' \'));\n      }\n\n      if (!next.rows.length) {\n        throw new Error(\'No player rows were found.\');\n      }\n\n      if (next.rows.length > 1000) {\n        throw new Error(\'Use no more than 1,000 players in one import.\');\n      }\n\n      const created = await invoke(\'migration_create_batch\', {\n        entity_type: \'players\',\n        source_label: sourceName || \'Player roster CSV\',\n        field_mapping: next.fieldMapping,\n        metadata: {\n          profile: \'agency_player_roster_v1\',\n          source: \'agency_workspace_csv\',\n        },\n      });\n\n      const batchId = String(created?.result?.batch_id || \'\');\n      if (!batchId) {\n        throw new Error(\'Migration batch could not be created.\');\n      }\n\n      const response = await invoke(\'migration_preflight\', {\n        batch_id: batchId,\n        rows: next.rows,\n      });\n\n      if (!response?.migration?.batch?.id) {\n        throw new Error(\'Migration preflight returned no batch.\');\n      }\n\n      setMigration(response.migration);\n    } catch (previewError) {\n      setError(\n        previewError instanceof Error\n          ? previewError.message\n          : \'Roster preflight failed.\',\n      );\n    } finally {\n      setBusy(\'\');\n    }\n  };\n\n  const decide = async (\n    rowId: string,\n    decision: \'create\' | \'skip\',\n  ) => {\n    const batchId = migration?.batch?.id;\n    if (!batchId) return;\n\n    setBusy(`row:${rowId}`);\n    setError(\'\');\n\n    try {\n      await invoke(\'migration_row_decision\', {\n        batch_id: batchId,\n        row_id: rowId,\n        decision,\n      });\n      await refreshBatch(batchId);\n    } catch (decisionError) {\n      setError(\n        decisionError instanceof Error\n          ? decisionError.message\n          : \'Decision could not be saved.\',\n      );\n    } finally {\n      setBusy(\'\');\n    }\n  };\n\n  const approveAndImport = async () => {\n    const batchId = migration?.batch?.id;\n    if (!batchId || !migration?.approval_gate?.can_approve) return;\n\n    setBusy(\'apply\');\n    setError(\'\');\n\n    try {\n      await invoke(\'migration_approve\', {\n        batch_id: batchId,\n      });\n\n      const response = await invoke(\'migration_apply\', {\n        batch_id: batchId,\n      });\n\n      setApplied(response?.result || null);\n      await refreshBatch(batchId);\n      await onImported();\n    } catch (applyError) {\n      setError(\n        applyError instanceof Error\n          ? applyError.message\n          : \'Roster import failed.\',\n      );\n    } finally {\n      setBusy(\'\');\n    }\n  };\n\n  const warnings =\n    migration?.rows?.filter(\n      (row) => row.validation_state === \'warning\',\n    ) || [];\n  const blocked =\n    migration?.rows?.filter(\n      (row) => row.validation_state === \'blocked\',\n    ) || [];\n\n  return (\n    <div className={styles.backdrop}>\n      <section\n        className={styles.panel}\n        role="dialog"\n        aria-modal="true"\n        aria-label="Player roster migration"\n      >\n        <header className={styles.header}>\n          <div>\n            <p>PLAYER ROSTER MIGRATION</p>\n            <h2>Bring {workspaceName}\'s players in.</h2>\n          </div>\n          <button type="button" onClick={onClose} aria-label="Close">\n            <X size={18} />\n          </button>\n        </header>\n\n        <div className={styles.explainer}>\n          <FileSpreadsheet size={18} />\n          <div>\n            <strong>Import an existing roster from CSV</strong>\n            <span>\n              Preflight checks every row first. Possible duplicates need a\n              human create or skip decision. Nothing is written until you\n              explicitly approve the import.\n            </span>\n          </div>\n        </div>\n\n        {!migration ? (\n          <>\n            <div className={styles.fileActions}>\n              <label className={styles.fileButton}>\n                <Upload size={15} />\n                Choose CSV\n                <input\n                  type="file"\n                  accept=".csv,text/csv"\n                  onChange={(event) => void readFile(event)}\n                />\n              </label>\n              <button type="button" onClick={downloadTemplate}>\n                <Download size={15} />\n                Download template\n              </button>\n            </div>\n\n            <textarea\n              value={csv}\n              onChange={(event) => {\n                setCsv(event.target.value);\n                setSourceName(\'Pasted CSV\');\n                resetReview();\n              }}\n              placeholder="Or paste CSV here..."\n              spellCheck={false}\n            />\n\n            {parsed ? (\n              <div className={styles.detected}>\n                <strong>{parsed.rows.length} players detected</strong>\n                <span>{parsed.headers.join(\' · \')}</span>\n              </div>\n            ) : null}\n          </>\n        ) : null}\n\n        {error ? (\n          <div className={styles.error}>\n            <CircleAlert size={15} />\n            <span>{error}</span>\n          </div>\n        ) : null}\n\n        {migration ? (\n          <div className={styles.review}>\n            <div className={styles.summary}>\n              <Summary label="Rows" value={migration.batch.row_count} />\n              <Summary label="Ready" value={migration.batch.valid_rows} />\n              <Summary label="Review" value={migration.batch.warning_rows} />\n              <Summary label="Blocked" value={migration.batch.blocked_rows} />\n            </div>\n\n            {blocked.length ? (\n              <section className={styles.issueSection}>\n                <h3>Fix before import</h3>\n                {blocked.slice(0, 12).map((row) => (\n                  <div className={styles.issueRow} key={row.row_id}>\n                    <div>\n                      <strong>{playerName(row)}</strong>\n                      <span>\n                        {row.issues\n                          .map((issue) => issue.message || issue.code)\n                          .filter(Boolean)\n                          .join(\' \')}\n                      </span>\n                    </div>\n                  </div>\n                ))}\n              </section>\n            ) : null}\n\n            {warnings.length ? (\n              <section className={styles.issueSection}>\n                <h3>Possible duplicates</h3>\n                {warnings.map((row) => (\n                  <div className={styles.issueRow} key={row.row_id}>\n                    <div>\n                      <strong>{playerName(row)}</strong>\n                      <span>\n                        {row.issues\n                          .map((issue) => issue.message || issue.code)\n                          .filter(Boolean)\n                          .join(\' \')}\n                      </span>\n                    </div>\n                    <div className={styles.decisions}>\n                      <button\n                        type="button"\n                        className={\n                          row.human_decision === \'skip\'\n                            ? styles.selected\n                            : \'\'\n                        }\n                        onClick={() => void decide(row.row_id, \'skip\')}\n                        disabled={Boolean(busy)}\n                      >\n                        Skip\n                      </button>\n                      <button\n                        type="button"\n                        className={\n                          row.human_decision === \'create\'\n                            ? styles.selected\n                            : \'\'\n                        }\n                        onClick={() => void decide(row.row_id, \'create\')}\n                        disabled={Boolean(busy)}\n                      >\n                        Create anyway\n                      </button>\n                    </div>\n                  </div>\n                ))}\n              </section>\n            ) : null}\n\n            {applied ? (\n              <div className={styles.success}>\n                <CheckCircle2 size={17} />\n                <div>\n                  <strong>Roster imported</strong>\n                  <span>\n                    {applied.created_entities || 0} players created\n                    {applied.skipped_rows\n                      ? ` · ${applied.skipped_rows} skipped`\n                      : \'\'}\n                  </span>\n                </div>\n              </div>\n            ) : null}\n          </div>\n        ) : null}\n\n        <footer className={styles.footer}>\n          {migration && !applied ? (\n            <button\n              type="button"\n              onClick={() => setMigration(null)}\n              disabled={Boolean(busy)}\n            >\n              Edit CSV\n            </button>\n          ) : (\n            <button type="button" onClick={onClose} disabled={Boolean(busy)}>\n              {applied ? \'Close\' : \'Cancel\'}\n            </button>\n          )}\n\n          {!migration ? (\n            <button\n              type="button"\n              className={styles.primary}\n              onClick={() => void runPreflight()}\n              disabled={!csv.trim() || Boolean(busy)}\n            >\n              {busy === \'preview\' ? (\n                <LoaderCircle size={15} className={styles.spin} />\n              ) : null}\n              Run preflight\n            </button>\n          ) : null}\n\n          {migration && !applied ? (\n            <button\n              type="button"\n              className={styles.primary}\n              onClick={() => void approveAndImport()}\n              disabled={\n                !migration.approval_gate.can_approve || Boolean(busy)\n              }\n            >\n              {busy === \'apply\' ? (\n                <LoaderCircle size={15} className={styles.spin} />\n              ) : (\n                <CheckCircle2 size={15} />\n              )}\n              Approve and import\n            </button>\n          ) : null}\n        </footer>\n      </section>\n    </div>\n  );\n}\n\nfunction Summary({\n  label,\n  value,\n}: {\n  label: string;\n  value: number;\n}) {\n  return (\n    <div>\n      <span>{label}</span>\n      <strong>{value || 0}</strong>\n    </div>\n  );\n}\n', 'components/AgencyRosterMigrationPanel.module.css': '.backdrop {\n  position: fixed;\n  inset: 0;\n  z-index: 120;\n  display: grid;\n  place-items: center;\n  padding: 20px;\n  background: rgba(10, 13, 18, .58);\n  backdrop-filter: blur(8px);\n}\n\n.panel {\n  width: min(760px, calc(100vw - 28px));\n  max-height: calc(100dvh - 32px);\n  overflow: auto;\n  box-sizing: border-box;\n  display: grid;\n  gap: 16px;\n  padding: 24px;\n  border: 1px solid #e1e4e8;\n  border-radius: 20px;\n  background: #fff;\n  box-shadow: 0 24px 80px rgba(0, 0, 0, .18);\n}\n\n.header {\n  display: flex;\n  justify-content: space-between;\n  gap: 20px;\n}\n\n.header p {\n  margin: 0 0 4px;\n  color: #7b8490;\n  font-size: 10px;\n  font-weight: 800;\n  letter-spacing: .14em;\n}\n\n.header h2 {\n  margin: 0;\n  font-size: 25px;\n  letter-spacing: -.035em;\n}\n\n.header button,\n.fileActions button,\n.footer button,\n.decisions button {\n  appearance: none;\n  border: 0;\n  cursor: pointer;\n  font: inherit;\n}\n\n.header button {\n  width: 34px;\n  height: 34px;\n  display: grid;\n  place-items: center;\n  flex: 0 0 auto;\n  border-radius: 9px;\n  background: #f2f3f5;\n  color: #59616c;\n}\n\n.explainer {\n  display: flex;\n  gap: 10px;\n  align-items: flex-start;\n  padding: 13px;\n  border-radius: 12px;\n  background: #f7f8f9;\n  color: #505965;\n}\n\n.explainer div {\n  display: grid;\n  gap: 3px;\n}\n\n.explainer strong {\n  font-size: 12px;\n}\n\n.explainer span {\n  color: #78818c;\n  font-size: 10px;\n  line-height: 1.45;\n}\n\n.fileActions {\n  display: flex;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.fileActions button,\n.fileButton {\n  min-height: 36px;\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  padding: 0 11px;\n  border-radius: 9px;\n  background: #eef0f2;\n  color: #434c57;\n  font-size: 10px;\n  font-weight: 750;\n  cursor: pointer;\n}\n\n.fileButton input {\n  display: none;\n}\n\n.panel textarea {\n  width: 100%;\n  min-height: 220px;\n  box-sizing: border-box;\n  resize: vertical;\n  border: 1px solid #dfe3e7;\n  border-radius: 12px;\n  padding: 13px;\n  outline: none;\n  background: #fbfcfd;\n  color: #252b33;\n  font: 500 11px/1.55 ui-monospace, SFMono-Regular, Menlo, monospace;\n}\n\n.detected {\n  display: grid;\n  gap: 3px;\n  padding: 10px 12px;\n  border-radius: 10px;\n  background: #f6f7f8;\n}\n\n.detected strong {\n  font-size: 11px;\n}\n\n.detected span {\n  overflow-wrap: anywhere;\n  color: #7b8490;\n  font-size: 9px;\n}\n\n.error,\n.success {\n  display: flex;\n  align-items: flex-start;\n  gap: 9px;\n  padding: 11px 12px;\n  border-radius: 10px;\n  font-size: 10px;\n  line-height: 1.45;\n}\n\n.error {\n  background: #fff1f0;\n  color: #93352e;\n}\n\n.success {\n  background: #eff8f2;\n  color: #29623a;\n}\n\n.success div {\n  display: grid;\n  gap: 2px;\n}\n\n.review {\n  display: grid;\n  gap: 14px;\n}\n\n.summary {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 8px;\n}\n\n.summary div {\n  display: grid;\n  gap: 3px;\n  padding: 12px;\n  border-radius: 10px;\n  background: #f5f6f7;\n}\n\n.summary span {\n  color: #7a828c;\n  font-size: 9px;\n  font-weight: 700;\n  text-transform: uppercase;\n}\n\n.summary strong {\n  font-size: 20px;\n}\n\n.issueSection {\n  display: grid;\n  gap: 7px;\n}\n\n.issueSection h3 {\n  margin: 0 0 2px;\n  font-size: 12px;\n}\n\n.issueRow {\n  display: flex;\n  justify-content: space-between;\n  gap: 14px;\n  padding: 11px 12px;\n  border: 1px solid #e7e9ec;\n  border-radius: 10px;\n}\n\n.issueRow > div:first-child {\n  min-width: 0;\n  display: grid;\n  gap: 3px;\n}\n\n.issueRow strong {\n  font-size: 11px;\n}\n\n.issueRow span {\n  color: #727b86;\n  font-size: 9px;\n  line-height: 1.4;\n}\n\n.decisions {\n  flex: 0 0 auto;\n  display: flex;\n  gap: 5px;\n  align-items: center;\n}\n\n.decisions button {\n  min-height: 30px;\n  padding: 0 8px;\n  border-radius: 8px;\n  background: #f0f2f4;\n  color: #515a65;\n  font-size: 9px;\n  font-weight: 750;\n}\n\n.decisions button.selected {\n  background: #111827;\n  color: #fff;\n}\n\n.footer {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n  padding-top: 4px;\n}\n\n.footer button {\n  min-height: 39px;\n  padding: 0 14px;\n  border-radius: 10px;\n  background: #eff1f3;\n  color: #49525d;\n  font-size: 10px;\n  font-weight: 800;\n}\n\n.footer button.primary {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  background: #111827;\n  color: #fff;\n}\n\n.footer button:disabled,\n.decisions button:disabled {\n  opacity: .45;\n  cursor: not-allowed;\n}\n\n.spin {\n  animation: roster-migration-spin .8s linear infinite;\n}\n\n@keyframes roster-migration-spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n@media (max-width: 640px) {\n  .backdrop {\n    align-items: end;\n    padding: 8px;\n  }\n\n  .panel {\n    width: 100%;\n    max-height: 92dvh;\n    padding: 17px;\n    border-radius: 18px 18px 10px 10px;\n  }\n\n  .panel textarea {\n    min-height: 180px;\n  }\n\n  .summary {\n    grid-template-columns: 1fr 1fr;\n  }\n\n  .issueRow {\n    display: grid;\n  }\n\n  .decisions {\n    justify-content: flex-start;\n  }\n\n  .footer {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n  }\n\n  .fileActions {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n  }\n\n  .fileActions button,\n  .fileButton {\n    justify-content: center;\n  }\n}\n', 'tests/agency-roster-migration-v1.test.ts': 'import assert from \'node:assert/strict\';\nimport { readFileSync } from \'node:fs\';\nimport test from \'node:test\';\n\nimport {\n  parseRosterMigrationCsv,\n  rosterMigrationTemplate,\n} from \'../lib/agency-roster-migration.ts\';\n\nconst read = (path: string) => readFileSync(path, \'utf8\');\n\ntest(\'roster CSV maps common agency spreadsheet headings into canonical player rows\', () => {\n  const parsed = parseRosterMigrationCsv(\n    [\n      \'Player Name,Position,Current Club,Nationality,Contract Expiry\',\n      \'"Alex Example",RW,"Example FC","Netherlands;Belgium",2027-06-30\',\n    ].join(\'\\n\'),\n  );\n\n  assert.equal(parsed.errors.length, 0);\n  assert.equal(parsed.rows.length, 1);\n  assert.equal(parsed.rows[0].normalized.first_name, \'Alex\');\n  assert.equal(parsed.rows[0].normalized.last_name, \'Example\');\n  assert.deepEqual(\n    parsed.rows[0].normalized.nationalities,\n    [\'Netherlands\', \'Belgium\'],\n  );\n});\n\ntest(\'roster CSV preserves quoted commas and explicit first and last names\', () => {\n  const parsed = parseRosterMigrationCsv(\n    [\n      \'First Name,Last Name,Current Club\',\n      \'Jean Pierre,"van Dijk","Rotterdam, FC"\',\n    ].join(\'\\n\'),\n  );\n\n  assert.equal(parsed.rows[0].normalized.first_name, \'Jean Pierre\');\n  assert.equal(parsed.rows[0].normalized.last_name, \'van Dijk\');\n  assert.equal(parsed.rows[0].normalized.current_club, \'Rotterdam, FC\');\n});\n\ntest(\'roster template is usable CSV and not a JSON migration workflow\', () => {\n  assert.match(\n    rosterMigrationTemplate,\n    /First Name,Last Name,Position/,\n  );\n  assert.doesNotMatch(rosterMigrationTemplate, /^\\s*\\{/);\n});\n\ntest(\'roster migration reuses the existing tenant migration engine\', () => {\n  const panel = read(\n    \'components/AgencyRosterMigrationPanel.tsx\',\n  );\n  const edge = read(\'supabase/functions/agency-os/index.ts\');\n\n  assert.match(panel, /migration_create_batch/);\n  assert.match(panel, /migration_preflight/);\n  assert.match(panel, /migration_row_decision/);\n  assert.match(panel, /migration_approve/);\n  assert.match(panel, /migration_apply/);\n\n  assert.match(edge, /platform_server_create_migration_batch/);\n  assert.match(edge, /platform_server_migration_preflight/);\n  assert.match(edge, /platform_server_apply_migration_batch/);\n});\n\ntest(\'duplicate warnings require an explicit create or skip decision\', () => {\n  const panel = read(\n    \'components/AgencyRosterMigrationPanel.tsx\',\n  );\n\n  assert.match(panel, /Create anyway/);\n  assert.match(panel, />\\s*Skip\\s*</);\n  assert.match(panel, /approval_gate\\.can_approve/);\n  assert.match(panel, /Nothing is written until you/);\n});\n\ntest(\'roster import is an owner admin operations setup utility, not a fifth daily workspace\', () => {\n  const workspace = read(\n    \'components/AgencyOperatingWorkspace.tsx\',\n  );\n\n  assert.match(workspace, /Import roster/);\n  assert.match(workspace, /AgencyRosterMigrationPanel/);\n  assert.match(\n    workspace,\n    /\\[\'owner\', \'admin\', \'operations\'\\]/,\n  );\n  assert.doesNotMatch(workspace, /label: \'Import\'/);\n});\n'}
for rel, content in files.items():
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding='utf-8')
    print(f'Wrote {rel}')

workspace_path = ROOT / 'components/AgencyOperatingWorkspace.tsx'
workspace = workspace_path.read_text(encoding='utf-8')
import_anchor = "import { supabase } from '@/lib/supabase';\n"
migration_import = "import AgencyRosterMigrationPanel from '@/components/AgencyRosterMigrationPanel';\n"
if migration_import not in workspace:
    if import_anchor not in workspace:
        raise SystemExit('Expected Supabase import anchor not found.')
    workspace = workspace.replace(import_anchor, import_anchor + migration_import, 1)
state_anchor = "  const [proposal, setProposal] = useState<any>(null);\n"
migration_state = "  const [rosterImportOpen, setRosterImportOpen] = useState(false);\n"
if migration_state not in workspace:
    if state_anchor not in workspace:
        raise SystemExit('Expected proposal state anchor not found.')
    workspace = workspace.replace(state_anchor, state_anchor + migration_state, 1)

old_header = '''          <button\n            type="button"\n            className={styles.refresh}\n            onClick={() => void loadView()}\n            disabled={busy}\n          >\n            <RefreshCw\n              size={15}\n              className={busy ? styles.spin : ''}\n            />\n            Refresh\n          </button>\n'''
new_header = '''          <div className={styles.headActions}>\n            {view === 'home' &&\n            ['owner', 'admin', 'operations'].includes(\n              workspace.role,\n            ) ? (\n              <button\n                type="button"\n                className={styles.refresh}\n                onClick={() => setRosterImportOpen(true)}\n              >\n                Import roster\n              </button>\n            ) : null}\n            <button\n              type="button"\n              className={styles.refresh}\n              onClick={() => void loadView()}\n              disabled={busy}\n            >\n              <RefreshCw\n                size={15}\n                className={busy ? styles.spin : ''}\n              />\n              Refresh\n            </button>\n          </div>\n'''
if old_header in workspace:
    workspace = workspace.replace(old_header, new_header, 1)
elif 'Import roster' not in workspace:
    raise SystemExit('Expected workspace refresh header not found.')

proposal_anchor = '''      {proposal ? (\n        <div className={styles.modalBackdrop}>\n'''
panel_block = '''      {rosterImportOpen ? (\n        <AgencyRosterMigrationPanel\n          workspaceName={workspaceName}\n          invoke={invoke}\n          onClose={() => setRosterImportOpen(false)}\n          onImported={async () => {\n            await loadView();\n          }}\n        />\n      ) : null}\n\n'''
if panel_block not in workspace:
    if proposal_anchor not in workspace:
        raise SystemExit('Expected proposal modal anchor not found.')
    workspace = workspace.replace(proposal_anchor, panel_block + proposal_anchor, 1)
workspace_path.write_text(workspace, encoding='utf-8')
print('Connected roster migration to agency workspace.')

css_path = ROOT / 'components/AgencyOperatingWorkspace.module.css'
workspace_css = css_path.read_text(encoding='utf-8')
if '.headActions {' not in workspace_css:
    workspace_css += '''\n.headActions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n\n@media (max-width: 680px) {\n  .headActions {\n    gap: 5px;\n  }\n\n  .headActions .refresh:first-child {\n    padding: 8px 9px;\n    font-size: 9px;\n  }\n}\n'''
    css_path.write_text(workspace_css, encoding='utf-8')
    print('Added workspace header action styling.')

for rel in [*files.keys(), 'components/AgencyOperatingWorkspace.tsx', 'components/AgencyOperatingWorkspace.module.css']:
    if '\u2014' in (ROOT / rel).read_text(encoding='utf-8'):
        raise SystemExit(f'Literal U+2014 found in {rel}')
print('Player roster migration v1 applied. No database change and no commit created.')
